window.docContents[3].resolve({"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Typing--Typing-Relation":{"contents":"                              Γ x = τ₁\n                            ------------                       (var)\n                             Γ ⊢ x ⦂ τ₁\n\n                        x ↦ τ₂ ; Γ ⊢ t₁ ⦂ τ₁\n                      -------------------------                (abs)\n                       Γ ⊢ λx:τ₂. t₁ ⦂ τ₂ → τ₁\n\n                          Γ ⊢ t₁ ⦂ τ₂ → τ₁\n                            Γ ⊢ t₂ ⦂ τ₂\n                         ------------------                    (app)\n                           Γ ⊢ t₁ t₂ ⦂ τ₁\n\n                          -----------------                    (tru)\n                           Γ ⊢ true ⦂ Bool\n\n                         ------------------                    (fls)\n                          Γ ⊢ false ⦂ Bool\n\n             Γ ⊢ t₁ ⦂ Bool    Γ ⊢ t₂ ⦂ τ₁    Γ ⊢ t₃ ⦂ τ₁\n            ---------------------------------------------      (ite)\n                   Γ ⊢ if t₁ then t₂ else t₃ ⦂ τ₁\n\n\nWe can read the three-place relation Γ ⊢ t ⦂ T as:\n\"under the assumptions in Γ, the term t has the type T.\"\n\n\n\nIn the formal development, we write this judgment inside the same\n<{ .. }> brackets.\n\n\n\ninductive HasType : Context → Tm → Ty → Prop where\n  | var (Γ : Context) (x : String) (τ₁ : Ty)\n      (h : Γ[x] = some τ₁) :\n      <{ Γ ⊢ ~(Tm.var x) ⦂ τ₁ }>\n  | abs (Γ : Context) (x : String)\n      (τ₁ τ₂ : Ty) (t₁ : Tm)\n      (h : <{ x ↦ τ₂ ; Γ ⊢ t₁ ⦂ τ₁ }>) :\n      <{ Γ ⊢ λ x : τ₂ . t₁ ⦂ τ₂ → τ₁ }>\n  | app (Γ : Context) (τ₁ τ₂ : Ty)\n      (t₁ t₂ : Tm)\n      (h₁ : <{ Γ ⊢ t₁ ⦂ τ₂ → τ₁ }>)\n      (h₂ : <{ Γ ⊢ t₂ ⦂ τ₂ }>) :\n      <{ Γ ⊢ t₁ t₂ ⦂ τ₁ }>\n  | tru (Γ : Context) :\n       <{ Γ ⊢ true ⦂ Bool }>\n  | fls (Γ : Context) :\n       <{ Γ ⊢ false ⦂ Bool }>\n  | ite (Γ : Context) (t₁ t₂ t₃ : Tm) (τ₁ : Ty)\n      (h₁ : <{ Γ ⊢ t₁ ⦂ Bool }>)\n      (h₂ : <{ Γ ⊢ t₂ ⦂ τ₁ }>)\n      (h₃ : <{ Γ ⊢ t₃ ⦂ τ₁ }>) :\n      <{ Γ ⊢ if t₁ then t₂ else t₃ ⦂ τ₁ }>\n\n\nattribute [StlcTyping] HasType.var HasType.abs HasType.app HasType.tru HasType.fls HasType.ite\n\n\nopen Lean PrettyPrinter in\n@[app_unexpander HasType]\ndef HasType.unexpand : Unexpander := StlcCommon.Delab.unexpandHasType\n\n\n/-- info: <{ ∅ ⊢ true ⦂ Bool }> : Prop -/\n#guard_msgs in\n#check <{ ∅ ⊢ true ⦂ Bool }>\n\n/-- info: <{ X ↦ Bool ; ∅ ⊢ X ⦂ Bool }> : Prop -/\n#guard_msgs in\n#check HasType\n  (PartialMap.update (∅ : Context) \"X\" Ty.bool)\n  (Tm.var \"X\")\n  Ty.bool\n\n/-- info: fun Γ t τ => <{ Z ↦ Bool ; Γ ⊢ t ⦂ τ }> : Context → Tm → Ty → Prop -/\n#guard_msgs in\n#check fun (Γ : Context) (t : Tm) (τ : Ty) => <{ Z ↦ Bool ; Γ ⊢ t ⦂ τ }>\n\n\n","context":"Type Systems\u0009Stlc: The Simply Typed Lambda-Calculus\u0009Typing","header":"5.4.2. Typing Relation","id":"/Stlc/#Type-Systems--Stlc___-The-Simply-Typed-Lambda-Calculus--Typing--Typing-Relation"},"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Substitution":{"contents":"\n\nThe substitution lemma is stated exactly as in pure STLC.The proof is also the same except that here it is easier to use\ninduction on typing derivations rather than on terms.\n\ntheorem substitution_preserves_typing {Γ : Context} {x : String} {τ₁ : Ty} {t v : Tm} {τ : Ty}\n    (ht : <{ x ↦ τ₁ ; Γ ⊢ t ⦂ τ }>)\n    (hv : <{ ∅ ⊢ v ⦂ τ₁ }>) :\n    <{ Γ ⊢ [x := v] t ⦂ τ }> := by\n\n  generalize heq : x →ₚ τ₁ ; Γ = Γ' at ht\n  induction ht generalizing x Γ with (\n    subst_vars; try rw [subst]; try (apply_rules using StlcSubTyping; done))\n  | var Γ y σ h =>\n      by_cases h₁ : x = y\n      · subst h₁; simp at h; subst h;\n        apply weakening_empty at hv\n        simp; assumption\n      · rw [PartialMap.update_neq] at h <;> simp_all\n        apply_rules using StlcSubTyping\n  | abs _ y _ _ _ h ih =>\n      by_cases h₁ : x = y\n      · simp_all [PartialMap.update_shadow]; apply_rules using StlcSubTyping\n      · simp_all; constructor; apply ih; rw [PartialMap.update_permute]; lia\n  | sub Γ t₁ τ₁ τ₂ ht hs ih =>\n      apply HasType.sub <;> solve_by_elim using StlcSubTyping\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Properties","header":"8.3.6. Substitution","id":"/Sub/#Type-Systems--Sub___-Subtyping--Properties--Substitution"}});